package dev.jdguo.bank.ledger;
import dev.jdguo.bank.currency.BankConfig;
import java.math.*;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LandBuybackTest {
 final UUID admin=UUID.randomUUID(),seller=UUID.randomUUID(),other=UUID.randomUUID();
 final BigInteger amount=BigInteger.valueOf(7);
 BankBooks funded(){var b=BankBooks.create(BankConfig.defaults());b.creditHeld(admin,"note",new BigDecimal("20"));assertTrue(b.transferTreasury(admin,"note",new BigDecimal("20"),true).success());assertTrue(b.fundSystemAccount(admin,true,"land",new BigDecimal("10"),new BigDecimal("20"),BigDecimal.ZERO).success());return b;}
 void eq(String s,BigDecimal n){assertEquals(0,new BigDecimal(s).compareTo(n));}
 @Test void strictCompletionRejectsMissingUnrelatedAndReversedReceipts(){var b=funded();assertFalse(b.completeLandBuyback("market-pay:absent").success());b.creditHeld(other,"note",BigDecimal.ONE);var q=b.quoteLandPurchase("note",BigInteger.ONE,"note");assertTrue(b.payLandPurchase(other,"note",BigInteger.ONE,"note",q.get("fingerprint").getAsString(),"market-pay:other").success());String before=b.toJson();assertEquals("kind",b.completeLandBuyback("market-pay:other").code());assertEquals(before,b.toJson());assertTrue(b.prepareLandBuyback(seller,"note",amount,"market-pay:strict").success());assertTrue(b.refundLandBuyback(seller,"note",amount,"market-pay:strict","refund:strict").success());assertEquals("reversed",b.completeLandBuyback("market-pay:strict").code());assertTrue(b.prepareLandBuyback(seller,"note",amount,"market-pay:valid").success());assertTrue(b.completeLandBuyback("market-pay:valid").success());assertTrue(b.completeLandBuyback("market-pay:valid").success());eq("7",b.balanceExact(seller,"note"));b.checkInvariants();}
 @Test void escrowSurvivesRestartAndPaysOnceOnlyAfterDelivery(){var b=funded();var supply=b.supply("note").liabilityExact();assertTrue(b.prepareLandBuyback(seller,"note",amount,"market-pay:one").success());eq("0",b.balanceExact(seller,"note"));eq("3",b.systemAvailableBalance("land","note"));b.checkInvariants();b=BankBooks.fromJson(b.toJson(),BankConfig.defaults());assertTrue(b.prepareLandBuyback(seller,"note",amount,"market-pay:one").success());assertTrue(b.completeSystemPayment("market-pay:one").success());assertTrue(b.completeSystemPayment("market-pay:one").success());eq("7",b.balanceExact(seller,"note"));assertTrue(b.transferSavings(seller,other,"note",amount).success());assertFalse(b.refundLandBuyback(seller,"note",amount,"market-pay:one","refund:one").success());eq("7",b.balanceExact(other,"note"));assertEquals(supply,b.supply("note").liabilityExact());b.checkInvariants();}
 @Test void refundCannotDependOnSellerFundsAndRecallCannotSpendEscrow(){var b=funded();assertTrue(b.prepareLandBuyback(seller,"note",amount,"market-pay:two").success());assertTrue(b.recallSystemAccount(admin,true,"land",new BigDecimal("3"),b.systemRecallCapacity("land")).success());eq("0",b.systemAvailableBalance("land","note"));assertTrue(b.refundLandBuyback(seller,"note",amount,"market-pay:two","refund:two").success());assertTrue(b.refundLandBuyback(seller,"note",amount,"market-pay:two","refund:two").success());eq("7",b.systemAvailableBalance("land","note"));eq("0",b.balanceExact(seller,"note"));assertFalse(b.completeSystemPayment("market-pay:two").success());b.checkInvariants();}
 @Test void invalidAndConflictingRequestsAreNoOps(){var b=funded();String before=b.toJson();assertFalse(b.quoteLandBuyback(seller,"diamond",amount).success());assertFalse(b.prepareLandBuyback(seller,"note",BigInteger.valueOf(11),"market-pay:x").success());assertFalse(b.prepareLandBuyback(seller,"note",amount,"market-pay:").success());assertEquals(before,b.toJson());assertTrue(b.prepareLandBuyback(seller,"note",amount,"market-pay:x").success());before=b.toJson();assertFalse(b.prepareLandBuyback(other,"note",amount,"market-pay:x").success());assertFalse(b.refundLandBuyback(other,"note",amount,"market-pay:x","refund:x").success());assertFalse(b.refundLandBuyback(seller,"note",amount,"market-pay:x","refund:y").success());assertEquals(before,b.toJson());}
 @Test void pendingIncomingIsNotSpentAndCompletedSettledBucketIsRestored(){var b=funded();b.creditHeld(other,"note",BigDecimal.TEN);for(String ref:new String[]{"incoming-done","incoming-pending"}){var q=b.quoteLandPurchase("note",BigInteger.valueOf(5),"note");assertTrue(b.payLandPurchase(other,"note",BigInteger.valueOf(5),"note",q.get("fingerprint").getAsString(),ref).success());}assertTrue(b.completeSystemPayment("incoming-done").success());assertTrue(b.prepareLandBuyback(seller,"note",BigInteger.valueOf(15),"market-pay:mix").success());eq("0",b.systemAvailableBalance("land","note"));eq("5",b.systemSettlementBalance("land","note"));b.checkInvariants();assertTrue(b.refundLandBuyback(seller,"note",BigInteger.valueOf(15),"market-pay:mix","refund:mix").success());eq("10",b.systemFundingBalance("land"));eq("10",b.systemSettlementBalance("land","note"));eq("15",b.systemAvailableBalance("land","note"));b.checkInvariants();}
}
